function levelAverages(root: TreeNode | null): number[] {
  const sum: number[] = [], count: number[] = [];
  const walk = (node: TreeNode | null, depth: number): void => {
    if (!node) return;
    if (depth === sum.length) { sum.push(0); count.push(0); }
    sum[depth] += node.val;
    count[depth]++;
    walk(node.left, depth + 1);
    walk(node.right, depth + 1);
  };
  walk(root, 0);
  return sum.map((s, d) => s / count[d]);
}

