class Solution:
    def levelAverages(self, root: Optional[TreeNode]) -> List[float]:
        total, count = [], []
        stack = [(root, 0)]
        while stack:
            node, depth = stack.pop()
            if not node:
                continue
            if depth == len(total):
                total.append(0)
                count.append(0)
            total[depth] += node.val
            count[depth] += 1
            stack.append((node.right, depth + 1))
            stack.append((node.left, depth + 1))
        return [t / c for t, c in zip(total, count)]

