    def levelAverages(self, root: Optional[TreeNode]) -> List[float]:
        out = []
        q = deque([root] if root else [])
        while q:
            size, total = len(q), 0
            for _ in range(size):
                node = q.popleft()
                total += node.val
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            out.append(total / size)
        return out

